use vstd::prelude::*;

verus! {

    // A specification function that says every element of the sequence `s`
    // is strictly less than the threshold `t`.
    spec fn all_below(s: Seq<i8>, t: i8) -> bool {
        forall |i: nat| i < s.len() ==> s.index(i) < t
    }

    // Checks whether every element in the Vec `l` is strictly less than `t`.
    // Returns true exactly when the spec predicate `all_below(l@, t)` holds.
    fn check_below_threshold(l: Vec<i8>, t: i8) -> bool
        ensures
            // `l@` is the immutable snapshot of `l` as a Seq<i8>.
            result == all_below(l@, t)
    {
        let mut i: usize = 0;
        // Loop over all indices 0..l.len()
        while i < l.len()
            invariant
                // For all indices j < i, we have already checked l[j] < t.
                forall |j: nat| j < i as nat ==> l@.index(j) < t,
            decreases
                // We make progress because i increases toward l.len()
                (l.len() - i) as nat
        {
            // Safe to index because i < l.len()
            let v: i8 = l[i];
            if v >= t {
                // Found a violation, hence the overall result is false.
                return false;
            }
            i += 1;
        }
        // No violations found, so every element is < t
        true
    }
}

